    const currentParts = getZonedParts(current, timeZone);
    const weekdayIndex = zonedWeekdayIndex(current, timeZone);
    let daysToAdd = 0;

    if (weekdayIndex === 6) {
      daysToAdd = 2;
    } else if (weekdayIndex === 0) {
      daysToAdd = 1;
    } else {
      return current;
    }

    const nextDay = addZonedDays(currentParts, daysToAdd);
    return zonedDateTimeToUtc({
      ...nextDay,
      hour: 0,
      minute: 0,
      second: 0
    }, timeZone);
  }

  function weekendStartFromWeekday(value, timeZone = SOURCE_TIMEZONE) {
    const current = parseIso(value);
    if (!current) return null;
    const currentParts = getZonedParts(current, timeZone);
    const weekdayIndex = zonedWeekdayIndex(current, timeZone);
    if (weekdayIndex < 1 || weekdayIndex > 5) return current;

    const daysToSaturday = 6 - weekdayIndex;
    const saturday = addZonedDays(currentParts, daysToSaturday);
    return zonedDateTimeToUtc({
      ...saturday,
      hour: 0,
      minute: 0,
      second: 0
    }, timeZone);
  }

  function computeWeekdayActiveForecastWindowEnd(sealedAtValue, activeDurationMs, timeZone = SOURCE_TIMEZONE) {
    let cursor = parseIso(sealedAtValue);
    if (!cursor) return null;

    let remainingMs = activeDurationMs;

    while (remainingMs > 0) {
      if (isWeekendInTimeZone(cursor, timeZone)) {
        cursor = nextWeekdayOpenFrom(cursor, timeZone);
        continue;
      }

      const weekendStart = weekendStartFromWeekday(cursor, timeZone);
      if (!weekendStart) return null;

      const activeChunkMs = Math.min(remainingMs, weekendStart.getTime() - cursor.getTime());
      cursor = new Date(cursor.getTime() + activeChunkMs);
      remainingMs -= activeChunkMs;

      if (remainingMs > 0) {
        cursor = nextWeekdayOpenFrom(weekendStart, timeZone);
      }
    }

    return cursor.toISOString();
  }

  function computeForecastWindowEnd(sealedAtValue, asset = "", horizonDuration = DEFAULT_HORIZON_DURATION) {
    const sealedAt = parseIso(sealedAtValue);
    if (!sealedAt) return null;

    if (horizonDuration !== DEFAULT_HORIZON_DURATION) return null;

    if (!assetUsesWeekdayActiveExpiry(asset)) {
      return new Date(sealedAt.getTime() + (24 * 60 * 60 * 1000)).toISOString();
    }

    return computeWeekdayActiveForecastWindowEnd(sealedAt, 24 * 60 * 60 * 1000, SOURCE_TIMEZONE);
  }

  function deriveLayer1StatusAtBuild(agent = {}, dashboardMeta = {}) {
    const priorityCall = agent.priority_call || agent.calls?.["24h"] || {};
    const direction = priorityCall.direction;
    const sealedAt = chooseSealedAt(agent);
    const statusAtBuild = String(agent.status_at_build || priorityCall.status_at_build || "").toUpperCase();

    if (statusAtBuild) return statusAtBuild;
    if (!sealedAt || isPendingDirection(direction)) return "UNAVAILABLE";
    if (isWeekendBlockedAsset(agent.agent) && isWeekendInTimeZone(sealedAt, SOURCE_TIMEZONE) && isExplicitNoCallDirection(direction)) {
      return "MARKET_CLOSED";
    }
    if (isExplicitNoCallDirection(direction)) return "NO_CALL";
    return "ACTIVE";
  }

  function buildLayer1Timing(agent = {}, dashboardMeta = {}) {
    const executionClock = dashboardMeta.execution_clock || DEFAULT_EXECUTION_CLOCK;
    const scheduleMeta = provisionalScheduleMetadata(dashboardMeta);
    const generatedAt = chooseGeneratedAt(agent);
    const sealedAt = chooseSealedAt(agent);
    const validFrom = agent.valid_from || sealedAt;
    const refreshDueAt = agent.refresh_due_at || computeNextRefreshDueAt(validFrom || sealedAt, executionClock, SOURCE_TIMEZONE);
    const priorityCall = agent.priority_call || agent.calls?.["24h"] || {};
    const horizonCode = agent.horizon_code || priorityCall.horizon_code || "24H";
    const horizonDuration = agent.horizon_duration || priorityCall.horizon_duration || DEFAULT_HORIZON_DURATION;
    const horizonBasis = agent.horizon_basis || priorityCall.horizon_basis || assetHorizonBasis(agent.agent);
    const marketCalendar = agent.market_calendar || priorityCall.market_calendar || assetMarketCalendar(agent.agent);
    const explicitForecastWindowEnd = firstPresentValue(
      agent.forecast_window_end,
      priorityCall.forecast_window_end,
      agent.expires_at,
      priorityCall.expires_at
    );
    const forecastWindowEnd = explicitForecastWindowEnd ?? computeForecastWindowEnd(validFrom || sealedAt, agent.agent, horizonDuration);
    const statusAtBuild = deriveLayer1StatusAtBuild(agent, dashboardMeta);

    return {
      generated_at: generatedAt,
      sealed_at: sealedAt,
      valid_from: validFrom,
      refresh_due_at: refreshDueAt,
      forecast_window_end: forecastWindowEnd,
      expires_at: forecastWindowEnd,
      status_at_build: statusAtBuild,
      effective_status: String(agent.effective_status || priorityCall.effective_status || statusAtBuild).toUpperCase(),
      status_resolved_at: agent.status_resolved_at || priorityCall.status_resolved_at || null,
      horizon_code: horizonCode,
      horizon_duration: horizonDuration,
      horizon_basis: horizonBasis,
      timezone: agent.timezone || priorityCall.timezone || SOURCE_TIMEZONE,
      market_calendar: marketCalendar,
      source_run_id: chooseSourceRunId(agent),
      validity_note: agent.validity_note || priorityCall.validity_note || "Operational freshness uses a provisional refresh expectation only. Forecast expiry is explicit and separate from the provisional refresh threshold.",
      horizon_note: agent.horizon_note || priorityCall.horizon_note || (assetUsesWeekdayActiveExpiry(agent.agent) ? DEFAULT_HORIZON_NOTE : ""),
      ...scheduleMeta
    };
  }

  function requiresExplicitForecastExpiry(agent = {}, timing = {}, priorityCall = {}) {
    const horizonCode = String(timing.horizon_code || priorityCall.horizon_code || "").toUpperCase();
    const statusAtBuild = String(timing.status_at_build || priorityCall.status_at_build || "").toUpperCase();
    const direction = priorityCall.direction;
    return horizonCode === "24H"
      && timing.horizon_duration === DEFAULT_HORIZON_DURATION
      && !isPendingDirection(direction)
      && !isExplicitNoCallDirection(direction)
      && !["UNAVAILABLE", "MARKET_CLOSED", "SUPERSEDED"].includes(statusAtBuild);
  }

  function assertValidExplicitLayer1Expiry(agent = {}, timing = {}, priorityCall = {}) {
    if (!requiresExplicitForecastExpiry(agent, timing, priorityCall)) {
      return;
    }

    const forecastWindowEnd = parseIso(timing.forecast_window_end);
    if (!forecastWindowEnd) {
      throw new Error(
        `Unable to derive explicit 24H forecast expiry for ${agent.agent || "UNKNOWN"} `
        + `(valid_from=${timing.valid_from || "null"}, sealed_at=${timing.sealed_at || "null"}, `
        + `forecast_window_end=${timing.forecast_window_end ?? "null"})`
      );
    }

    if (timing.expires_at !== timing.forecast_window_end) {
      throw new Error(
        `Explicit 24H expiry mismatch for ${agent.agent || "UNKNOWN"} `
        + `(forecast_window_end=${timing.forecast_window_end ?? "null"}, expires_at=${timing.expires_at ?? "null"})`
      );
    }
  }

  function resolveLayer1DisplayStatus(agent = {}, dashboardMeta = {}, nowValue = new Date()) {
    const timing = buildLayer1Timing(agent, dashboardMeta);
    const priorityCall = agent.priority_call || agent.calls?.["24h"] || {};
    const now = parseIso(nowValue) || new Date();
    const refreshDueAt = parseIso(timing.refresh_due_at);
    const forecastWindowEnd = parseIso(timing.forecast_window_end);

    if (!timing.sealed_at || isPendingDirection(priorityCall.direction)) return "UNAVAILABLE";
    if (timing.status_at_build === "SUPERSEDED") return "SUPERSEDED";
    if (timing.status_at_build === "UNAVAILABLE") return "UNAVAILABLE";

    if (isWeekendBlockedAsset(agent.agent) && isWeekendInTimeZone(now, SOURCE_TIMEZONE) && isExplicitNoCallDirection(priorityCall.direction)) {
      return "MARKET_CLOSED";
    }

    if (isExplicitNoCallDirection(priorityCall.direction)) return "NO_CALL";
    if (forecastWindowEnd && now.getTime() >= forecastWindowEnd.getTime()) return "EXPIRED";
    if (refreshDueAt && now.getTime() >= refreshDueAt.getTime()) return "STALE";
    return "ACTIVE";
  }

  function buildLayer2Timing({ pairCode, pairLabel, targetLeg, usdLeg, nowValue = new Date() }) {
    const targetAgent = targetLeg?.agent || null;
    const usdAgent = usdLeg?.agent || null;
    const now = parseIso(nowValue) || new Date();
    const targetStatus = targetAgent ? resolveLayer1DisplayStatus(targetAgent, targetLeg.dashboardMeta, now) : "UNAVAILABLE";
    const usdStatus = usdAgent ? resolveLayer1DisplayStatus(usdAgent, usdLeg.dashboardMeta, now) : "UNAVAILABLE";
    const targetTiming = targetAgent ? buildLayer1Timing(targetAgent, targetLeg.dashboardMeta) : {};
    const usdTiming = usdAgent ? buildLayer1Timing(usdAgent, usdLeg.dashboardMeta) : {};

    const targetValidFrom = parseIso(targetTiming.valid_from);
    const usdValidFrom = parseIso(usdTiming.valid_from);
    const targetRefreshDueAt = parseIso(targetTiming.refresh_due_at);
    const usdRefreshDueAt = parseIso(usdTiming.refresh_due_at);
    const targetForecastEnd = parseIso(targetTiming.forecast_window_end);
    const usdForecastEnd = parseIso(usdTiming.forecast_window_end);

    const pairValidFrom = targetValidFrom && usdValidFrom
      ? new Date(Math.max(targetValidFrom.getTime(), usdValidFrom.getTime())).toISOString()
      : (targetValidFrom || usdValidFrom)?.toISOString() || null;
    const pairRefreshDueAt = targetRefreshDueAt && usdRefreshDueAt
      ? new Date(Math.min(targetRefreshDueAt.getTime(), usdRefreshDueAt.getTime())).toISOString()
      : (targetRefreshDueAt || usdRefreshDueAt)?.toISOString() || null;
    const pairForecastEnd = targetForecastEnd && usdForecastEnd
      ? new Date(Math.min(targetForecastEnd.getTime(), usdForecastEnd.getTime())).toISOString()
      : null;
    const pairStartDate = parseIso(pairValidFrom);
    const pairEndDate = parseIso(pairForecastEnd);
    const forecastWindowsOverlap = Boolean(pairStartDate && pairEndDate && pairStartDate.getTime() < pairEndDate.getTime());

    let effectiveStatus = "ACTIVE";
    let statusAtBuild = "ACTIVE";
    let reason = null;

    if (!targetAgent || !usdAgent) {
      effectiveStatus = "UNAVAILABLE";
      statusAtBuild = "UNAVAILABLE";
      reason = "Missing supporting Layer 1 leg";
    } else if (!forecastWindowsOverlap) {
      effectiveStatus = "UNAVAILABLE";
      statusAtBuild = "UNAVAILABLE";
      reason = "Supporting Layer 1 forecast windows do not overlap";
    } else if (["UNAVAILABLE", "MARKET_CLOSED", "SUPERSEDED"].includes(targetStatus) || ["UNAVAILABLE", "MARKET_CLOSED", "SUPERSEDED"].includes(usdStatus)) {
      effectiveStatus = "UNAVAILABLE";
      statusAtBuild = "UNAVAILABLE";
    } else if (targetStatus === "NO_CALL" || usdStatus === "NO_CALL") {
      effectiveStatus = "NO_CALL";
      statusAtBuild = "NO_CALL";
    } else if ((targetForecastEnd && now.getTime() >= targetForecastEnd.getTime()) || (usdForecastEnd && now.getTime() >= usdForecastEnd.getTime()) || (pairEndDate && now.getTime() >= pairEndDate.getTime())) {
      effectiveStatus = "EXPIRED";
      statusAtBuild = "ACTIVE";
    } else if (targetStatus === "STALE" || usdStatus === "STALE") {
      effectiveStatus = "STALE";
      statusAtBuild = "ACTIVE";
    }

    return {
      pair_code: pairCode || null,
      pair_label: pairLabel || null,
      valid_from: effectiveStatus === "UNAVAILABLE" && reason ? null : pairValidFrom,
      refresh_due_at: effectiveStatus === "UNAVAILABLE" && reason ? null : pairRefreshDueAt,
      forecast_window_end: effectiveStatus === "UNAVAILABLE" && reason ? null : pairForecastEnd,
      expires_at: effectiveStatus === "UNAVAILABLE" && reason ? null : pairForecastEnd,
      status_at_build: statusAtBuild,
      effective_status: effectiveStatus,
      status_resolved_at: now.toISOString(),
      timezone: SOURCE_TIMEZONE,
      horizon_code: "24H",
      horizon_duration: DEFAULT_HORIZON_DURATION,
      horizon_basis: "PAIR_SUPPORTING_FORECAST_INTERSECTION_V1",
      market_calendar: `${targetTiming.market_calendar || assetMarketCalendar(targetAgent?.agent)}__${usdTiming.market_calendar || assetMarketCalendar(usdAgent?.agent)}`,
      reason,
      supporting_legs: {
        target: {
          asset: targetLeg.agent?.agent || null,
          effective_status: targetStatus,
          valid_from: targetTiming.valid_from || null,
          refresh_due_at: targetTiming.refresh_due_at || null,
          forecast_window_end: targetTiming.forecast_window_end || null,
          expires_at: targetTiming.expires_at || null,
          sealed_at: targetTiming.sealed_at || null,
          source_run_id: targetTiming.source_run_id || null
        },
        usd: {
          asset: usdLeg.agent?.agent || null,
          effective_status: usdStatus,
          valid_from: usdTiming.valid_from || null,
          refresh_due_at: usdTiming.refresh_due_at || null,
          forecast_window_end: usdTiming.forecast_window_end || null,
          expires_at: usdTiming.expires_at || null,
          sealed_at: usdTiming.sealed_at || null,
          source_run_id: usdTiming.source_run_id || null
        }
      }
    };
  }

  function resolveLayer2DisplayStatus(pair = {}, nowValue = new Date()) {
    const storedStatus = String(pair.effective_status || pair.status_at_build || "UNAVAILABLE").toUpperCase();
    const now = parseIso(nowValue) || new Date();
    const refreshDueAt = parseIso(pair.refresh_due_at);
    const forecastWindowEnd = parseIso(pair.forecast_window_end || pair.expires_at);

    if (storedStatus === "UNAVAILABLE" || storedStatus === "MARKET_CLOSED" || storedStatus === "SUPERSEDED") return "UNAVAILABLE";
    if (storedStatus === "NO_CALL") return "NO_CALL";
    if (forecastWindowEnd && now.getTime() >= forecastWindowEnd.getTime()) return "EXPIRED";
    if (storedStatus === "STALE" || (refreshDueAt && now.getTime() >= refreshDueAt.getTime())) return "STALE";
    return "ACTIVE";
  }

  function formatDisplayTime(value, timeZone = DISPLAY_TIMEZONE) {
    const date = parseIso(value);
    if (!date) return "Pending";
    return new Intl.DateTimeFormat("en-GB", {
      timeZone,
      day: "2-digit",
      month: "short",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false
    }).format(date);
  }

  function formatRemainingDuration(targetValue, nowValue = new Date()) {
    const target = parseIso(targetValue);
    const now = parseIso(nowValue) || new Date();
    if (!target) return null;

    const diffMs = target.getTime() - now.getTime();
    if (diffMs <= 0) return null;

    const totalMinutes = Math.ceil(diffMs / 60000);
    const days = Math.floor(totalMinutes / 1440);
    const hours = Math.floor((totalMinutes % 1440) / 60);
    const minutes = totalMinutes % 60;
    const parts = [];

    if (days > 0) parts.push(`${days}d`);
    if (hours > 0) parts.push(`${hours}h`);
    if ((minutes > 0 || parts.length === 0) && parts.length < 2) parts.push(`${minutes}m`);

    return parts.join(" ");
  }

  function formatTimeUntilRefresh(refreshDueAtValue, nowValue = new Date()) {
    const remaining = formatRemainingDuration(refreshDueAtValue, nowValue);
    if (!parseIso(refreshDueAtValue)) return "Awaiting refresh schedule";
    if (!remaining) return "refresh overdue";
    return `refresh due in ${remaining}`;
  }

  function formatTimeUntilForecastExpiry(forecastWindowEndValue, nowValue = new Date()) {
    const forecastWindowEnd = parseIso(forecastWindowEndValue);
    if (!forecastWindowEnd) return "Awaiting forecast expiry";
    const remaining = formatRemainingDuration(forecastWindowEnd, nowValue);
    if (!remaining) return "expired";
    return `expires in ${remaining}`;
  }

  function enrichLayer1DashboardData(data = {}) {
    const dashboardMeta = data.dashboard_meta || {};
    const scheduleMeta = provisionalScheduleMetadata(dashboardMeta);
    const nowIso = new Date().toISOString();
    const agents = (data.agents || []).map((rawAgent) => {
      const timing = buildLayer1Timing(rawAgent, dashboardMeta);
      const effectiveStatus = resolveLayer1DisplayStatus(rawAgent, dashboardMeta, new Date());
      assertValidExplicitLayer1Expiry(rawAgent, timing, rawAgent.priority_call || rawAgent.calls?.["24h"] || {});
      const calls = { ...(rawAgent.calls || {}) };
      const call24 = { ...(calls["24h"] || {}) };
      call24.generated_at = call24.generated_at || timing.generated_at;
      call24.sealed_at = call24.sealed_at || timing.sealed_at;
      call24.valid_from = call24.valid_from || timing.valid_from;
      call24.refresh_due_at = call24.refresh_due_at || timing.refresh_due_at;
      call24.forecast_window_end = Object.prototype.hasOwnProperty.call(call24, "forecast_window_end") ? call24.forecast_window_end : timing.forecast_window_end;
      call24.expires_at = Object.prototype.hasOwnProperty.call(call24, "expires_at") ? call24.expires_at : timing.expires_at;
      call24.status_at_build = call24.status_at_build || timing.status_at_build;
      call24.effective_status = effectiveStatus;
      call24.status_resolved_at = nowIso;
      call24.horizon_code = call24.horizon_code || timing.horizon_code;
      call24.horizon_duration = call24.horizon_duration || timing.horizon_duration;
      call24.horizon_basis = call24.horizon_basis || timing.horizon_basis;
      call24.timezone = call24.timezone || timing.timezone;
      call24.market_calendar = call24.market_calendar || timing.market_calendar;
      call24.source_run_id = call24.source_run_id || timing.source_run_id;
      call24.validity_note = call24.validity_note || timing.validity_note;
      call24.horizon_note = call24.horizon_note || timing.horizon_note;
      calls["24h"] = call24;

      return {
        ...rawAgent,
        ...timing,
        effective_status: effectiveStatus,
        status_resolved_at: nowIso,
        calls,
        priority_call: {
          ...(rawAgent.priority_call || call24),
          ...call24
        }
      };
    });

    return {
      ...data,
      dashboard_meta: {
        ...dashboardMeta,
        display_timezone: dashboardMeta.display_timezone || DISPLAY_TIMEZONE,
        validity_contract_version: dashboardMeta.validity_contract_version || "live_v3_explicit_forecast_expiry",
        timing_contract_note: dashboardMeta.timing_contract_note || "Forecast expiry is explicit and separate from the provisional refresh threshold. Refresh timing remains an operational expectation only.",
        horizon_contract_note: dashboardMeta.horizon_contract_note || DEFAULT_HORIZON_NOTE,
        ...scheduleMeta
      },
      agents
    };
  }

  return {
    SOURCE_TIMEZONE,
    DISPLAY_TIMEZONE,
    DEFAULT_EXECUTION_CLOCK,
    DEFAULT_HORIZON_DURATION,
    DEFAULT_PROVISIONAL_REFRESH_NOTE,
    DEFAULT_HORIZON_NOTE,
    WEEKDAY_ACTIVE_MARKET_CALENDAR,
    CRYPTO_MARKET_CALENDAR,
    assetHorizonBasis,
    assetMarketCalendar,
    buildLayer1Timing,
    buildLayer2Timing,
    computeForecastWindowEnd,
    computeNextRefreshDueAt,
    computeWeekdayActiveForecastWindowEnd,
    enrichLayer1DashboardData,
    formatDisplayTime,
    formatRemainingDuration,
    formatTimeUntilForecastExpiry,
    formatTimeUntilRefresh,
    isExplicitNoCallDirection,
    isNoCallDirection,
    isPendingDirection,
    isWeekendBlockedAsset,
    parseExecutionClockLabel,
    parseIso,
    provisionalScheduleMetadata,
    requiresExplicitForecastExpiry,
    resolveLayer1DisplayStatus,
    resolveLayer2DisplayStatus
  };
});


const rows = $input.all().map((item) => item.json);
const agents = ["USD", "EUR", "GOLD", "SILVER", "NQ", "BTC", "WTI", "GBP"];;

function parseMaybeJson(value, fallback = {}) {
  if (value === null || value === undefined || value === "") return fallback;
  if (typeof value === "object") return value;
  try {
    return JSON.parse(value);
  } catch (error) {
    return fallback;
  }
}

function parseMaybeArray(value, fallback = []) {
  if (value === null || value === undefined || value === "") return fallback;
  if (Array.isArray(value)) return value;
  try {
    const parsed = JSON.parse(value);
    return Array.isArray(parsed) ? parsed : fallback;
  } catch (error) {
    return fallback;
  }
}

function toNumber(value) {
  if (value === null || value === undefined || value === "") return null;
  const numeric = Number(value);
  return Number.isFinite(numeric) ? numeric : null;
}

function parseTimestamp(value) {
  const timestamp = new Date(value || 0).getTime();
  return Number.isFinite(timestamp) ? timestamp : 0;
}

function consistencyLabel(values) {
  if (!values.length) return "UNKNOWN";
  return values.every((value) => value === values[0]) ? "MATCHED" : "MISMATCHED";
}

function hasUsableDirection(row) {
  const output = parseMaybeJson(row && (row.full_output || row.raw_agent_output), {});
  return Boolean(row && (row.direction_24h || row.call_24h_direction || output.direction_24h || (output.today_call && output.today_call.direction)));
}

function selectLatestRowsByAgent() {
  const selected = {};
  const missingAgents = [];
  for (const agent of agents) {
    const latest = rows
      .filter((row) => row && row.agent_name === agent && Number(row.layer) === 1)
      .filter(hasUsableDirection)
      .sort((left, right) => parseTimestamp((right && (right.created_at || right.run_time_et)) || 0) - parseTimestamp((left && (left.created_at || left.run_time_et)) || 0))[0] || null;
    if (!latest) {
      missingAgents.push(agent);
      continue;
    }
    selected[agent] = latest;
  }
  if (missingAgents.length) {
    throw new Error("Missing required Layer 1 agents: " + missingAgents.join(", "));
  }
  return agents.map((agent) => selected[agent]);
}

function buildSelectionProvenance(selectedRows) {
  const sourceRunIds = selectedRows.map((row) => String((row && row.source_run_id) || "").trim()).filter(Boolean);
  const refreshRequestIds = selectedRows.map((row) => String((row && (row.refresh_request_id || row.request_id)) || "").trim()).filter(Boolean);
  const sourceRunConsistency = consistencyLabel(sourceRunIds);
  const refreshRequestConsistency = consistencyLabel(refreshRequestIds);
  const consistencyStatus = sourceRunConsistency === "MISMATCHED" || refreshRequestConsistency === "MISMATCHED"
    ? "MISMATCHED"
    : sourceRunConsistency === "MATCHED" || refreshRequestConsistency === "MATCHED"
      ? "MATCHED"
      : "UNKNOWN";
  return {
    sourceRunIds, refreshRequestIds, sourceRunConsistency, refreshRequestConsistency, consistencyStatus,
    sourceRunId: sourceRunConsistency === "MATCHED" ? sourceRunIds[0] : null,
    refreshRequestId: refreshRequestConsistency === "MATCHED" ? refreshRequestIds[0] : null
  };
}

function outputFromRow(row) {
  return parseMaybeJson(row.full_output, parseMaybeJson(row.raw_agent_output, {}));
}

function getDirection(row, output, oldField, newField) {
  return row[oldField] || row[newField] || output[newField] || "PENDING";
}

function getConviction(row, output, oldField, newField) {
  return toNumber(row[oldField] != null ? row[oldField] : row[newField] != null ? row[newField] : output[newField] != null ? output[newField] : null);
}

function buildKeyFactors(factorBreakdown) {
  if (!factorBreakdown || typeof factorBreakdown !== "object" || Array.isArray(factorBreakdown)) return [];
  return Object.entries(factorBreakdown).map(([key, value]) => {
    if (value && typeof value === "object") {
      const signal = value.signal || "NEUTRAL";
      const weight = value.weight !== undefined ? " [" + value.weight + "]" : "";
      const evidence = value.evidence ? " - " + value.evidence : "";
      const reason = value.reason ? " (" + value.reason + ")" : "";
      return key + weight + ": " + signal + evidence + reason;
    }
    return key + ": " + value;
  });
}

function normaliseConvictionModel(output, timeframeKey = "24h") {
  const timeframeModel = output.timeframe_models?.[timeframeKey] || {};
  const model = timeframeModel.conviction_model || output.conviction_model || {};
  const weightedScore = timeframeModel.weighted_score || output.weighted_score || {};
  const bullishArgument = toNumber(model.bullish_argument_pct);
  const bearishArgument = toNumber(model.bearish_argument_pct);
  const neutralPct = toNumber(model.neutral_evidence_pct ?? model.neutral_pct);
  const directionalParticipation = toNumber(model.directional_participation_pct ?? model.active_participation_pct);
  const netEdge = toNumber(model.net_edge_pct);
  const finalConviction = toNumber(model.final_conviction);
  const winningSide = model.winning_side || (bullishArgument !== null && bearishArgument !== null ? (bullishArgument > bearishArgument ? "BULLISH" : (bearishArgument > bullishArgument ? "BEARISH" : "TIED")) : null);
  return {
    ...model, bullish_argument_pct: bullishArgument, bearish_argument_pct: bearishArgument, neutral_pct: neutralPct, neutral_evidence_pct: neutralPct,
    directional_participation_pct: directionalParticipation, active_participation_pct: directionalParticipation, net_edge_pct: netEdge, final_conviction: finalConviction,
    verdict_strength: model.verdict_strength || null, winning_side: winningSide, final_conviction_logic: model.final_conviction_logic || "",
    bull_case_weight: toNumber(model.bull_case_weight ?? weightedScore.bullish_weight ?? null),
    bear_case_weight: toNumber(model.bear_case_weight ?? weightedScore.bearish_weight ?? null),
    neutral_weight: toNumber(model.neutral_weight ?? weightedScore.neutral_weight ?? null),
    weighted_score: {
      bullish_weight: toNumber(weightedScore.bullish_weight ?? model.bull_case_weight ?? null),
      bearish_weight: toNumber(weightedScore.bearish_weight ?? model.bear_case_weight ?? null),
      neutral_weight: toNumber(weightedScore.neutral_weight ?? model.neutral_weight ?? null),
      active_weight: toNumber(weightedScore.active_weight ?? directionalParticipation ?? null),
      weight_margin: toNumber(weightedScore.weight_margin ?? null)
    },
    alignment: bullishArgument, base_conviction: finalConviction, participation: directionalParticipation
  };
}

function timeframeModel(output, key) { return output.timeframe_models?.[key] || {}; }

function callObject(row, output, key, oldDirection, newDirection, oldConviction, newConviction, oldReason, newReason) {
  const tfModel = timeframeModel(output, key);
  return {
    direction: getDirection(row, output, oldDirection, newDirection),
    conviction: getConviction(row, output, oldConviction, newConviction),
    reason: row[oldReason] || output[newReason] || tfModel.reason || row.reasoning_summary || output.reasoning_summary || "",
    conviction_model: normaliseConvictionModel(output, key),
    weighted_score: tfModel.weighted_score || output.weighted_score || {},
    factor_breakdown: tfModel.factor_breakdown || output.factor_breakdown || {}
  };
}

function fromRow(agent, row) {
  const output = outputFromRow(row);
  const factorBreakdown = parseMaybeJson(row.factor_breakdown, output.factor_breakdown || {});
  const warnings = parseMaybeArray(row.warnings, output.risk_flags || output.warnings || []);
  const baseCalls = {
    "24h": callObject(row, output, "24h", "call_24h_direction", "direction_24h", "call_24h_conviction", "conviction_24h", "call_24h_reason", "reason_24h"),
    "3d": callObject(row, output, "3d", "call_3d_direction", "direction_3_day", "call_3d_conviction", "conviction_3_day", "call_3d_reason", "reason_3_day"),
    "current_week": callObject(row, output, "current_week", "call_current_week_direction", "direction_current_week", "call_current_week_conviction", "conviction_current_week", "call_current_week_reason", "reason_current_week"),
    "next_week": callObject(row, output, "next_week", "call_next_week_direction", "direction_next_week", "call_next_week_conviction", "conviction_next_week", "call_next_week_reason", "reason_next_week"),
    "current_month": callObject(row, output, "current_month", "call_current_month_direction", "direction_current_month", "call_current_month_conviction", "conviction_current_month", "call_current_month_reason", "reason_current_month")
  };
  const priorityTimeframe = "24h";
  const priorityCall = baseCalls[priorityTimeframe];
  const convictionModel = normaliseConvictionModel(output, priorityTimeframe);
  return {
    agent, status: "live", market_status: output.market_status || row.market_status || null, last_run_et: row.run_time_et || row.created_at || null,
    generated_at: row.run_time_et || row.created_at || null, sealed_at: row.created_at || output.created_at || row.run_time_et || null,
    valid_from: row.valid_from || output.valid_from || row.created_at || output.created_at || row.run_time_et || null,
    refresh_due_at: row.refresh_due_at || output.refresh_due_at || null,
    forecast_window_end: Object.prototype.hasOwnProperty.call(row, "forecast_window_end") ? row.forecast_window_end : (Object.prototype.hasOwnProperty.call(output, "forecast_window_end") ? output.forecast_window_end : null),
    expires_at: Object.prototype.hasOwnProperty.call(row, "expires_at") ? row.expires_at : (Object.prototype.hasOwnProperty.call(output, "expires_at") ? output.expires_at : null),
    status_at_build: row.status_at_build || output.status_at_build || priorityCall.status_at_build || null,
    effective_status: row.effective_status || output.effective_status || priorityCall.effective_status || null,
    status_resolved_at: row.status_resolved_at || output.status_resolved_at || null,
    horizon_code: row.horizon_code || output.horizon_code || priorityCall.horizon_code || "24H",
    horizon_duration: row.horizon_duration || output.horizon_duration || priorityCall.horizon_duration || "PT24H",
    horizon_basis: row.horizon_basis || output.horizon_basis || priorityCall.horizon_basis || null,
    timezone: row.timezone || output.timezone || priorityCall.timezone || "America/New_York",
    market_calendar: row.market_calendar || output.market_calendar || priorityCall.market_calendar || null,
    source_run_id: row.source_run_id || output.source_run_id || output.execution_id || output.workflow_execution_id || null,
    refresh_request_id: row.refresh_request_id || row.request_id || output.refresh_request_id || output.request_id || null,
    summary: output.summary || row.reasoning_summary || (agent + " Layer 1 raw call generated from sealed independent workflow."),
    calls: baseCalls, priority_timeframe: priorityTimeframe, priority_call: priorityCall, factor_breakdown: factorBreakdown, key_factors: buildKeyFactors(factorBreakdown),
    warnings, reasoning_summary: row.reasoning_summary || output.reasoning_summary || "", score_bullish: toNumber(row.score_bullish ?? output.score_bullish ?? null),
    score_bearish: toNumber(row.score_bearish ?? output.score_bearish ?? null), score_neutral: toNumber(row.score_neutral ?? output.score_neutral ?? null),
    non_neutral_count: toNumber(output.non_neutral_count ?? null), logic_document: row.logic_document || output.logic_document || null,
    logic_document_version: row.logic_document_version || output.logic_document_version || null, conviction_model: convictionModel, timeframe_models: output.timeframe_models || {},
    display_metrics: { bull_case: convictionModel.bullish_argument_pct, bear_case: convictionModel.bearish_argument_pct, winning_side: convictionModel.winning_side, conviction: convictionModel.final_conviction, net_edge: convictionModel.net_edge_pct, directional_participation: convictionModel.directional_participation_pct, neutral: convictionModel.neutral_evidence_pct ?? convictionModel.neutral_pct, verdict_strength: convictionModel.verdict_strength, bull_case_weight: convictionModel.bull_case_weight ?? null, bear_case_weight: convictionModel.bear_case_weight ?? null },
    full_output: output
  };
}

const selectedRows = selectLatestRowsByAgent();
const provenance = buildSelectionProvenance(selectedRows);
const rowByAgent = Object.fromEntries(selectedRows.map((row) => [row.agent_name, row]));
const baseDashboard = {
